const CDP_PORT = 9223;
const targets = await (await fetch(`http://127.0.0.1:${CDP_PORT}/json`)).json();
const page = targets.find(t => t.type === 'page' && t.url.includes('index.html'));
const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
await new Promise(r => ws.onopen = r);
function send(method, params = {}) { return new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({id:i, method, params})); }); }
await send('Runtime.enable');
async function evaluate(expr) { const r = await send('Runtime.evaluate', {expression: expr, returnByValue: true, awaitPromise: true}); return r.result?.result?.value; }

async function measure() { return await evaluate(`(() => {
  const o = { vw: innerWidth, scrollW: document.documentElement.scrollWidth, bodyW: document.body.scrollWidth };
  o.overflow = o.scrollW > o.vw;
  o.els = [...document.querySelectorAll('body *')].filter(e => e.getBoundingClientRect().right > o.vw + 1).map(e => e.tagName + '.' + e.className).slice(0,10);
  return o;
})()`); }

await send('Emulation.setDeviceMetricsOverride', {width:390,height:844,deviceScaleFactor:1,mobile:true});
console.log('MOBILE', JSON.stringify(await measure()));
await send('Emulation.setDeviceMetricsOverride', {width:1280,height:800,deviceScaleFactor:1,mobile:false});
console.log('DESKTOP', JSON.stringify(await measure()));

// Functional tests at mobile width
await send('Emulation.setDeviceMetricsOverride', {width:390,height:844,deviceScaleFactor:1,mobile:true});
console.log('TOGGLE', JSON.stringify(await evaluate(`(() => {
  const t = document.getElementById('readingToggle'); t.click();
  const on = document.body.classList.contains('reading-mode') && t.getAttribute('aria-pressed')==='true';
  t.click();
  const off = !document.body.classList.contains('reading-mode') && t.getAttribute('aria-pressed')==='false';
  return {on, off, label: document.getElementById('readingToggleText').textContent};
})()`)));
console.log('FORM', JSON.stringify(await evaluate(`(() => {
  const f = document.getElementById('subscribeForm'), i = document.getElementById('email'), s = document.getElementById('emailStatus');
  let nav = false; f.addEventListener('submit', e => { if(!e.defaultPrevented) nav = true; });
